import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p38_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor l1norm_cuda(torch::Tensor x);

torch::Tensor l1norm(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    return l1norm_cuda(x);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("l1norm", &l1norm, "Fused L1 norm forward (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>

__inline__ __device__ float warp_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset >>= 1)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__global__ void l1norm_kernel(const float* __restrict__ x, float* __restrict__ out, int rows, int cols) {
    int row = blockIdx.x;
    if (row >= rows) return;

    const float* row_x = x + (long long)row * cols;
    float* row_out = out + (long long)row * cols;

    // Shared memory: one float per warp for partial sums, plus one for inv_mean
    extern __shared__ float smem[];
    int num_warps = (blockDim.x + 31) / 32;
    float* warp_sums = smem;          // [num_warps]
    float* inv_mean_ptr = smem + num_warps; // [1]

    int tid = threadIdx.x;
    int lane = tid & 31;
    int warp_id = tid >> 5;

    // Pass 1: accumulate abs values
    float local_sum = 0.0f;
    for (int c = tid; c < cols; c += blockDim.x) {
        local_sum += fabsf(row_x[c]);
    }

    // Warp reduction
    local_sum = warp_reduce_sum(local_sum);

    // Store warp partial sums
    if (lane == 0) {
        warp_sums[warp_id] = local_sum;
    }
    __syncthreads();

    // Final reduction by first warp
    if (warp_id == 0) {
        float val = (lane < num_warps) ? warp_sums[lane] : 0.0f;
        val = warp_reduce_sum(val);
        if (lane == 0) {
            float sum_abs = val;
            inv_mean_ptr[0] = (sum_abs > 0.0f) ? ((float)cols / sum_abs) : 0.0f;
        }
    }
    __syncthreads();

    float inv_mean = inv_mean_ptr[0];

    // Pass 2: normalize
    for (int c = tid; c < cols; c += blockDim.x) {
        row_out[c] = row_x[c] * inv_mean;
    }
}

torch::Tensor l1norm_cuda(torch::Tensor x) {
    int rows = x.size(0);
    int cols = x.size(1);
    auto out = torch::empty_like(x);

    int block_size = 256;
    int num_warps = (block_size + 31) / 32;
    // smem: num_warps floats for warp sums + 1 float for inv_mean
    int smem_bytes = (num_warps + 1) * sizeof(float);

    dim3 grid(rows);
    dim3 block(block_size);

    l1norm_kernel<<<grid, block, smem_bytes, at::cuda::getDefaultCUDAStream()>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        rows,
        cols
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs L1 normalization.
        """
    def __init__(self):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initializes the L1 normalization layer.
                """
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Applies L1 normalization to the input tensor.

                Args:
                    x (torch.Tensor): Input tensor of shape (..., dim, ...).

                Returns:
                    torch.Tensor: Output tensor with L1 normalization applied, same shape as input.
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if x.is_cuda and x.dtype == torch.float32 and x.dim() == 2 and x.is_contiguous():
            return _stark_get_extension().l1norm(x)
        return x / torch.mean(torch.abs(x), dim=1, keepdim=True)
        # <<<END_IMPROVE>>>

